import {expect} from '@playwright/test';
export async function observeFrameClears(page){await page.addInitScript(()=>{window.__frameClears=new WeakMap();for(const Class of [window.WebGLRenderingContext,window.WebGL2RenderingContext]){if(!Class)continue;const original=Class.prototype.clear;Class.prototype.clear=function(...args){const rows=window.__frameClears.get(this.canvas)||[];rows.push(performance.now());window.__frameClears.set(this.canvas,rows);return original.apply(this,args);};}});}
export const frameClears=canvas=>canvas.evaluate(c=>[...(window.__frameClears.get(c)||[])]);
export async function exerciseCappedCamera(page,canvas,cap,{steps=70}={}){const box=await canvas.boundingBox(),initial=(await frameClears(canvas)).length;await page.mouse.move(box.x+box.width*.2,box.y+box.height*.65);await page.mouse.down({button:'middle'});for(let i=1;i<=steps;i++){await page.mouse.move(box.x+box.width*.2+i*.5,box.y+box.height*.65+Math.sin(i/8)*10);await page.waitForTimeout(25);}await page.mouse.up({button:'middle'});const frames=(await frameClears(canvas)).slice(initial);expect(frames.length).toBeGreaterThan(2);for(let i=1;i<frames.length;i++)expect(frames[i]-frames[i-1]).toBeGreaterThan(1000/cap-15);return frames;}
export async function cappedIdle(page,canvas,cap){const interval=Math.ceil(1000/cap)+100;await expect.poll(async()=>{const n=(await frameClears(canvas)).length;await page.waitForTimeout(interval);return(await frameClears(canvas)).length===n;},{timeout:10000}).toBe(true);const n=(await frameClears(canvas)).length;await page.waitForTimeout(interval);expect((await frameClears(canvas)).length).toBe(n);}
